#pragma once
#include <stdint.h>

/* Data model generated by tools/extract_mascot.mjs: an SVG-like node tree (groups and rects)
 * plus GSAP-style property tracks. One renderer plays all four animations. */

enum { MANIM_WALKING, MANIM_GYM, MANIM_FLAG, MANIM_CONFETTI, MANIM_COUNT };

enum {
    MP_DISPLAY, MP_X, MP_Y, MP_ROT, MP_SY, MP_OX, MP_OY, MP_ATTR_Y,
    MP_MA, MP_MB, MP_MC, MP_MD, MP_ME, MP_MF, /* attribute transform matrix */
    MP_COUNT
};

typedef struct {
    float x, y, w, h;
} manim_rect_t;

typedef struct {
    int16_t parent; /* index within the animation, -1 for the root svg */
    uint8_t is_rect;
    uint8_t has_clip;
    manim_rect_t clip; /* in this group's coordinate space */
    manim_rect_t r;
    uint32_t color; /* sRGB hex */
    float base[MP_COUNT];
} manim_node_t;

typedef struct {
    uint16_t node;
    uint8_t prop;
    uint8_t tl;
    uint16_t seg_start;
    uint16_t seg_count;
} manim_track_t;

typedef struct {
    float t0, t1, v0, v1;
    uint8_t ease;
} manim_seg_t;

typedef struct {
    float delay, period;
    int8_t repeat; /* -1 loops forever, 0 plays once and holds */
} manim_tl_t;

typedef struct {
    const char *name;
    float vb_w, vb_h;
    uint16_t node_start, node_count, track_start, track_count, tl_start, tl_count;
} manim_anim_t;

extern const manim_node_t mascot_nodes[];
extern const manim_track_t mascot_tracks[];
extern const manim_seg_t mascot_segs[];
extern const manim_tl_t mascot_tls[];
extern const manim_anim_t mascot_anims[MANIM_COUNT];
extern const float mascot_data_scale; /* scale the walk distance was computed for */

/* Draws animation `anim` at time t (seconds since it started). (ox, oy) is the screen
 * position of the viewBox origin, scale is pixels per viewBox unit. */
void manim_draw(uint16_t *fb, int anim, float t, float ox, float oy, float scale);
